AWS CloudFront & WAF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_cloudfront_and_waf, "AWS CloudFront & WAF") {
    Component(cdn_edge_caching, "CDN Edge Caching", "AWS CloudFront", "Caches static assets and handles origin failover with Amazon S3.")
    Component(edge_security_and_ddos_mitigation, "Edge Security & DDoS Mitigation", "AWS WAF & AWS Shield Advanced", "Provides bot control and DDoS mitigation at the edge.")
    Component(request_routing_and_mtls_termination, "Request Routing & mTLS Termination", "AWS Certificate Manager & AWS App Mesh", "Terminates TLS 1.3 and routes requests securely to backend microservices via mTLS.")
}

Rel(cdn_edge_caching, edge_security_and_ddos_mitigation, "Inspects incoming requests")
Rel(edge_security_and_ddos_mitigation, request_routing_and_mtls_termination, "Forwards validated requests via mTLS over AWS App Mesh")

@enduml

Catalog & Search.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Catalog & Search container

Container_Boundary(catalog_search, "Catalog & Search") {
    Component(SearchController, "Search Controller", "Amazon ECS/EKS REST API", "Handles incoming catalog browsing and search requests routed from CloudFront & WAF.")
    Component(SearchEngineConnector, "Search Engine Connector", "Private VPC Networking, OpenSearch Client", "Executes catalog and keyword queries against OpenSearch on AWS.")
    Component(TelemetryEmitter, "Telemetry Emitter", "FluentBit, Amazon Kinesis Data Firehose", "Streams asynchronous search telemetry and PII-masked search analytics.")
}

Rel(SearchController, SearchEngineConnector, "Queries index", "Private VPC / OpenSearch Client")
Rel(SearchController, TelemetryEmitter, "Streams search telemetry", "FluentBit / Kinesis")

@enduml

Checkout/Payment.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Checkout/Payment container

Container_Boundary(checkout_payment, "Checkout/Payment") {
    Component(CartSessionManager, "Cart Session Manager", "Amazon ECS/EKS Container", "Manages shopping carts and session data.")
    Component(PaymentOrchestrator, "Payment Orchestrator", "Amazon ECS/EKS Container", "Handles payment orchestration, idempotency, and client-side tokenization with gateways.")
    Component(FulfillmentIntegrationService, "Fulfillment Integration Service", "Amazon ECS/EKS Container", "Interfaces with third-party shipping APIs to retrieve rates and dispatch orders.")
}

Rel(CartSessionManager, PaymentOrchestrator, "Passes cart and session details for transaction processing", "Internal REST/gRPC")
Rel(PaymentOrchestrator, FulfillmentIntegrationService, "Triggers order dispatch upon successful payment authorization", "Internal REST/gRPC")

@enduml
